// hw2_system_wrapper.sv - Verilator stand-in for the Vivado block design
// Same connections as vivado/create_bd.tcl: uBee_soc_0 + evt_gen_0.
// In Vivado this module is generated by "make_wrapper"; here it is written by hand
// so that sim/tb_hw2.sv can be used without changes.
module hw2_system_wrapper (
    input         clk_i_0,
    input         rst_ni_0,
    output        uart_tx_o_0,
    input  [31:0] gpio_in_i_0
);
    wire [31:0] awaddr, wdata, araddr, rdata;
    wire [2:0]  awprot, arprot;
    wire [3:0]  wstrb;
    wire [1:0]  bresp, rresp;
    wire        awvalid, awready, wvalid, wready, bvalid, bready;
    wire        arvalid, arready, rvalid, rready;
    wire [15:0] irq_vec;

    uBee_soc #(
        .IMEM_INIT_FILE ("hw2_imem.mem"),
        .DMEM_INIT_FILE ("hw2_dmem.mem")
    ) uBee_soc_0 (
        .clk_i (clk_i_0), .rst_ni (rst_ni_0),
        .ext_irq_i (irq_vec),
        .gpio_in_i (gpio_in_i_0), .gpio_out_o (), .gpio_oe_o (),
        .uart_tx_o (uart_tx_o_0), .uart_rx_i (1'b1),
        .m_axi_awaddr_o (awaddr), .m_axi_awvalid_o (awvalid), .m_axi_awready_i (awready), .m_axi_awprot_o (awprot),
        .m_axi_wdata_o (wdata), .m_axi_wstrb_o (wstrb), .m_axi_wvalid_o (wvalid), .m_axi_wready_i (wready),
        .m_axi_bresp_i (bresp), .m_axi_bvalid_i (bvalid), .m_axi_bready_o (bready),
        .m_axi_araddr_o (araddr), .m_axi_arvalid_o (arvalid), .m_axi_arready_i (arready), .m_axi_arprot_o (arprot),
        .m_axi_rdata_i (rdata), .m_axi_rresp_i (rresp), .m_axi_rvalid_i (rvalid), .m_axi_rready_o (rready),
        .trace_valid_o (), .trace_pc_o (), .trace_instruction_o (), .trace_rd_write_o (), .trace_rd_addr_o (),
        .trace_rd_data_o (), .trace_mem_valid_o (), .trace_mem_write_o (), .trace_mem_addr_o (),
        .trace_mem_wdata_o (), .trace_mem_wstrb_o (), .trace_trap_o (), .trace_cause_o (),
        .dbg_fetch_pc_o (), .dbg_if_pc_o (), .dbg_if_valid_o (), .dbg_ex_pc_o (), .dbg_ex_valid_o (),
        .dbg_mem_pc_o (), .dbg_mem_valid_o (), .dbg_wb_pc_o (), .dbg_wb_valid_o (), .dbg_rf_we_o (),
        .dbg_rf_waddr_o (), .dbg_rf_wdata_o (), .dbg_csr_mstatus_o (), .dbg_csr_mie_o (), .dbg_csr_mtvec_o (),
        .dbg_csr_mscratch_o (), .dbg_csr_mepc_o (), .dbg_csr_mcause_o (), .dbg_csr_mtval_o (), .dbg_csr_mip_o (),
        .dbg_csr_mcycle_o (), .dbg_csr_mcycleh_o (), .dbg_csr_minstret_o (), .dbg_csr_minstreth_o ()
`ifdef SIMULATION
        , .tb_dmem_we_i (1'b0), .tb_dmem_widx_i (32'd0), .tb_dmem_wdata_i (32'd0)
`endif
    );

    evt_gen evt_gen_0 (
        .s_axi_aclk (clk_i_0), .s_axi_aresetn (rst_ni_0),
        .s_axi_awaddr (awaddr), .s_axi_awprot (awprot), .s_axi_awvalid (awvalid), .s_axi_awready (awready),
        .s_axi_wdata (wdata), .s_axi_wstrb (wstrb), .s_axi_wvalid (wvalid), .s_axi_wready (wready),
        .s_axi_bresp (bresp), .s_axi_bvalid (bvalid), .s_axi_bready (bready),
        .s_axi_araddr (araddr), .s_axi_arprot (arprot), .s_axi_arvalid (arvalid), .s_axi_arready (arready),
        .s_axi_rdata (rdata), .s_axi_rresp (rresp), .s_axi_rvalid (rvalid), .s_axi_rready (rready),
        .irq_vec_o (irq_vec)
    );
endmodule
